use super::*;

impl Backend{
 pub(super) async fn connect(&mut self,key:Arc<ClientKey>,entry:Entry,addresses:Option<Vec<String>>)->Result<()>{
 if let Some(task)=self.reconnect_task.take(){task.abort();let _=task.await;}let profile_id=self.current_profile_id()?;let previous=self.client.take().or_else(||self.retired_clients.remove(&profile_id));let reusable=previous.as_ref().filter(|client|key.network_id()==Some(client.network_id())&&key.device_id()==client.client_id()).cloned();
 if let Some(client)=&previous{client.close();}self.active_record=ActiveRecord::None;self.key=None;self.active_entry=None;self.pushes=None;self.conversation=None;self.attachments.clear();
 self.state=Snapshot{generation:self.state.generation+1,status:"正在验证目标设备和成员目录。".into(),..Default::default()};self.publish();
 let reconnect=if let Some(addresses)=addresses{ReconnectTarget::Lan{entry:entry.clone(),addresses}}else{ReconnectTarget::Gateway(entry.clone())};let endpoint=match &reconnect{ReconnectTarget::Gateway(entry)=>Endpoint::Gateway(entry.clone()),ReconnectTarget::Lan{entry,addresses}=>Endpoint::Lan{node_id:entry.node_id.clone(),addresses:addresses.clone()},ReconnectTarget::Local(_)=>unreachable!()};let client=if let Some(client)=reusable{client.reconnect_or_offline(endpoint).await?}else{let network=key.network_id().context("请通过邀请加入，或在本机 Node 创建个人网络")?;let outbox=self.client_directory()?.join("outbox").join(network).join(key.device_id());match Client::open_offline(key.clone(),endpoint.clone(),outbox.clone()).await{Ok(client)=>client,Err(_)=>Client::open_or_offline(key.clone(),endpoint,outbox).await?}};
 self.state.network=Some(client.network_id().into());self.state.client_id=Some(client.client_id().into());self.reconnect=Some(reconnect);self.active_entry=Some(entry);self.key=Some(key);self.pushes=Some(client.subscribe());self.client=Some(client);
 if !self.client()?.is_online(){self.load_projection().await?;return Ok(())}self.remember_profile_hints()?;self.identity(IdentityAction::Directory).await?;self.refresh().await?;self.flush_prepared().await
 }
 pub(super) async fn maintain(&mut self)->Result<()>{if self.host.poll_owned()?{self.publish_host().await;}if self.state.online{let unreachable=self.state.nodes.iter().any(|node|!node.online&&!node.revoked);if self.last_record_read.elapsed()>=Duration::from_secs(300)||unreachable&&self.last_record_read.elapsed()>=Duration::from_secs(15){self.last_record_read=tokio::time::Instant::now();match self.active_record.clone(){ActiveRecord::None=>{},ActiveRecord::Work{conversation_id,work_id}=>self.read_work_detail(conversation_id,work_id).await?,ActiveRecord::Channel(channel_id)=>self.read_history(Some(channel_id),None).await?,ActiveRecord::Task(task_id)=>self.read_history(None,Some(task_id)).await?,}}return Ok(())}if self.state.private_block.is_some(){return Ok(())}if self.reconnect_task.is_some(){return Ok(())}if tokio::time::Instant::now()<self.retry_at{return Ok(())}let Some(previous)=self.client.clone()else{return Ok(())};let target=self.reconnect.clone().context("没有可重新验证的接入入口")?;self.retry_attempt=self.retry_attempt.saturating_add(1);self.retry_at=tokio::time::Instant::now()+Duration::from_secs((1u64<<self.retry_attempt.min(5)).min(30));self.state.generation+=1;self.state.writable=false;self.state.status="正在重新验证连接，未知操作不会重发。".into();self.publish();let endpoint=match target{ReconnectTarget::Gateway(entry)=>Endpoint::Gateway(entry),ReconnectTarget::Lan{entry,addresses}=>Endpoint::Lan{node_id:entry.node_id,addresses},ReconnectTarget::Local(identity)=>{let expected=self.active_entry.clone().context("本机接入身份缺失")?;let data_dir=identity.data_dir;let target=tokio::task::spawn_blocking(move||vibeface_client::LocalTarget::read(&data_dir,&expected)).await??;Endpoint::Local(target.grant(previous.client_id()).await?)}};let attempt=self.state.generation;let profile_id=self.current_profile_id()?;let recovered=self.recovered.clone();self.reconnect_task=Some(tokio::spawn(async move{let result=previous.reconnect(endpoint).await;let _=recovered.send(Reconnected{attempt,profile_id,result}).await;}));Ok(())}

 pub(super) async fn identity(&mut self,action:IdentityAction)->Result<()>{ensure!(!self.state.local_session,"本机会话没有成员管理权限，请先加入个人网络");let key=self.key.as_ref().context("本机身份尚未解锁")?.clone();let client=self.client()?.clone();let mut session=client.management_session()?;match action{
 IdentityAction::Directory=>{let directory=session.directory().await?;let members=serde_json::to_value(directory.view.members)?;self.state.members=serde_json::from_value(members)?;self.state.can_manage=self.state.members.iter().any(|m|m.device_id==key.device_id()&&m.manage);self.publish();},
 IdentityAction::Invite=>{let link=session.invite().await?;let _=self.emit(Event::Detail(vec![("邀请链接，请只交给本人设备".into(),link)])).await;},
 IdentityAction::Requests=>{self.state.joins=serde_json::from_value(serde_json::to_value(session.requests().await?)?)?;self.publish();},
 IdentityAction::Rename{device_id,name}=>{session.grant(&device_id,Some(&name),None).await?;},IdentityAction::Grant{device_id,manage}=>{session.grant(&device_id,None,Some(manage)).await?;},IdentityAction::Revoke(id)=>{session.revoke(&id).await?;},IdentityAction::Recovery(approve)=>{session.settle_recovery(approve).await?;},IdentityAction::ConfirmJoin(id)=>{session.confirm_join(&id).await?;},IdentityAction::GrantJoin{join_id,manage}=>{session.grant_join(&join_id,manage).await?;},IdentityAction::RejectJoin(id)=>{session.reject_join(&id).await?;}}
 Ok(())}
 pub(super) fn publish_identity_plan(&mut self){self.state.identity_plan=self.identity_plan.as_ref().map(|(_,plan)|IdentityPlanView{backup_path:plan.backup_path().display().to_string(),sha256:plan.backup_sha256(),network_id:plan.network_id().into(),state:format!("{:?}",plan.state())});self.publish();}
}
